using System.Linq;
using System.Collections;
using System.IO;
using UnityEngine;
using UnityEngine.SceneManagement;

// The fair uses its own profile directory. No normal slot is opened or replaced.
public sealed class GridShiftFairSession:MonoBehaviour {
 public static bool Active{get;private set;}public static bool Positioned{get;private set;}static string previousRoot;
 public static bool Prepare(out string error){error=null;if(Active){error="Uma demonstração já está ativa.";return false;}previousRoot=GridShiftProfiles.RootOverride;GridShiftProfiles.Logout();GridShiftProfiles.RootOverride=Path.Combine(string.IsNullOrEmpty(previousRoot)?Application.persistentDataPath:previousRoot,"FeiraSENAI2026");if(!GridShiftProfiles.Login("feira@gridshift.local","apresentacao-local",out error)||!GridShiftProfiles.Create(1,"GridShift · Feira SENAI 2026",true,out error)){GridShiftProfiles.RootOverride=previousRoot;GridShiftProfiles.Logout();return false;}Active=true;Positioned=false;if(!PlayerPrefs.HasKey("GS.Perf.Preset"))GridShiftPerformanceSettings.SelectPreset(1);DeliverySaveStore.OverridePath=null;DeliverySaveStore.Pending=null;DeliverySaveStore.StartFresh=true;var go=new GameObject("Fair session positioning");DontDestroyOnLoad(go);go.AddComponent<GridShiftFairSession>();return true;}
 public static void End(){if(!Active)return;GridShiftProfiles.RootOverride=previousRoot;GridShiftProfiles.Logout();Active=false;Positioned=false;}
 public static bool TryFindStart(PlayerMovement player,GridShiftActiveConfig cfg,out Vector3 at,out Quaternion rotation){rotation=cfg.depotRotation*Quaternion.Euler(0,90,0);at=cfg.depotPosition;var cc=player.GetComponent<CharacterController>();float radius=cc.radius*Mathf.Max(player.transform.lossyScale.x,player.transform.lossyScale.z),height=cc.height*player.transform.lossyScale.y;foreach(float side in new[]{0f,-1f,1f,-2f,2f}){var candidate=cfg.depotPosition-cfg.depotRotation*Vector3.forward*1.8f+cfg.depotRotation*Vector3.right*side;if(!Physics.Raycast(candidate+Vector3.up,Vector3.down,out var floor,2.5f,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||floor.normal.y<.85f||Mathf.Abs(floor.point.y-cfg.depotPosition.y)>.6f)continue;candidate.y=floor.point.y+.08f;var bottom=candidate+Vector3.up*(radius+.05f);var top=candidate+Vector3.up*(height-radius);if(Physics.OverlapCapsule(bottom,top,radius,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.transform.IsChildOf(player.transform)))continue;if(Physics.CapsuleCastAll(bottom,top,radius,rotation*Vector3.forward,2.6f,~0,QueryTriggerInteraction.Ignore).Any(h=>!h.transform.IsChildOf(player.transform)))continue;at=candidate;return true;}return false;}
 IEnumerator Start(){while(SceneManager.GetActiveScene().name!="SampleScene"||DeliveryManager.Instance?.GetComponent<GridShiftActiveOperations>()?.Van==null||WorldSession.Instance.Busy)yield return null;var m=DeliveryManager.Instance;var p=InteractionFocus.PlayerFor(m);var cfg=m.GetComponent<GridShiftActiveOperations>().Config;Vector3 at;Quaternion rotation;while(!TryFindStart(p,cfg,out at,out rotation))yield return new WaitForSeconds(.25f);var controller=p.GetComponent<CharacterController>();controller.enabled=false;p.transform.SetPositionAndRotation(at,rotation);p.CameraTransform.localRotation=Quaternion.identity;Physics.SyncTransforms();controller.enabled=true;Positioned=true;m.GetComponent<DeliveryPersistence>().RequestSave();Destroy(gameObject);}
}
